cell_map = {}
for r,c,val in valid_pixels:
    rs = next(i for i,(a,b) in enumerate(row_cells) if a <= r < b)
    cs = next(j for j,(a,b) in enumerate(col_cells) if a <= c < b)
    if (rs,cs) not in cell_map:
        cell_map[(rs,cs)] = set()
    cell_map[(rs,cs)].add(val)

print("Cells by position:", dict(cell_map))
# Expected: {(1,0):{2}, (1,5):{2}, (5,0):{3}, (5,3):{3}}

# Now build output grid
output = [[0]*28 for _ in range(28)]

# Fill divider lines
for r in range(28):
    for c in range(28):
        if r in divs or c in divs:
            output[r][c] = 8
        else:
            # Find which cell region this belongs to
            rs = next(i for i,(a,b) in enumerate(row_cells) if a <= r < b)
            cs = next(j for j,(a,b) in enumerate(col_cells) if a <= c < b)

            if (rs, cs) in cell_map:
                colors = cell_map[(rs, cs)]
                # If single color, use it; otherwise check for 6 interaction
                if len(colors) == 1:
                    output[r][c] = list(colors)[0]
                else:
                    # Multiple colors in same cell → could be 6
                    output[r][c] = 6
            else:
                output[r][c] = 0

# Print result
for row in output:
    print(' '.join(map(str, row)))

